-- Шаг 74: PageSpeed курса (шаблон «Обучение», 15: 182 / 1182) — из чанка head-study убраны study.css, slimmenu.css и Google Fonts
-- Montserrat (с preconnect): их заменяет сокращённый course.css (подключает lb-head; Montserrat — с файлов редизайна). Повторный запуск
-- ничего не меняет.
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '    <link rel=\"stylesheet\" href=\"/assets/templates/css/study.css?ver=1.0.2\">\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/slimmenu.css\">\n    \n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n', '    {* старые стили курса (study.css + slimmenu.css) и Google Fonts Montserrat — один сокращённый course.css из lb-head (шаг 74):\n       Montserrat для старых блоков — с файлов редизайна, без запросов к fonts.googleapis.com / fonts.gstatic.com *}\n') WHERE name = 'head-study';
